import assert from 'node:assert/strict';
import { uniqueTags } from '../src/tags.js';

function check(input, expected) {
  const before = input.slice();
  assert.deepEqual(uniqueTags(Object.freeze(input)), expected);
  assert.deepEqual(input, before);
}
check(['JS', 'Node', 'js', 'NODE', 'css'], ['JS', 'Node', 'css']);
check(['a', 'A', 'b', 'B', 'a', 'C', 'c'], ['a', 'b', 'C']);
check(['CSS', 'css', 'CsS', 'HTML', 'html'], ['CSS', 'HTML']);
check(['', '', ' A', ' a', 'A ', 'a ', 'a', 'A'], ['', ' A', 'A ', 'a']);
check(['__proto__', '__PROTO__', 'constructor', 'CONSTRUCTOR', 'toString', 'TOSTRING'], ['__proto__', 'constructor', 'toString']);
check(['É', 'é', 'Ω', 'ω', 'Ж', 'ж', '猫', '猫'], ['É', 'Ω', 'Ж', '猫']);

// Deterministic shuffled interleaving: expected positions are derived from
// first occurrence, not from sorting or any implementation-specific helper.
let state = 918273;
const random = () => (state = (Math.imul(state, 1664525) + 1013904223) >>> 0);
const input = [];
for (let i = 0; i < 12000; i++) {
  const tag = 'tag-' + (random() % 173) + '-x';
  input.push(random() % 2 ? tag.toUpperCase() : tag);
}
const expected = [];
const seen = new Set();
for (const tag of input) {
  const key = tag.toLowerCase();
  if (!seen.has(key)) { seen.add(key); expected.push(tag); }
}
check(input, expected);
console.log('case-insensitive first-occurrence checks passed');

import assert from 'node:assert/strict';
import { uniqueTags } from '../src/tags.js';
for (const [input, expected] of [
  [[], []],
  [['node', 'js', 'node', 'css', 'js'], ['node', 'js', 'css']],
  [['z', 'a', 'm', 'z', 'a', 'q'], ['z', 'a', 'm', 'q']],
  [['', '', ' ', '  ', ' '], ['', ' ', '  ']],
  [['__proto__', 'constructor', 'toString', '__proto__'], ['__proto__', 'constructor', 'toString']],
  [['same', 'same', 'same'], ['same']],
]) {
  const before = input.slice();
  assert.deepEqual(uniqueTags(Object.freeze(input)), expected);
  assert.deepEqual(input, before);
}
console.log('existing behavior checks passed');

import assert from 'node:assert/strict';
import { performance } from 'node:perf_hooks';
import { uniqueTags } from '../src/tags.js';

const distinct = Array.from({length: 200000}, (_, i) => 'tag-' + i + '-value');
const mixed = distinct.concat(distinct.map(t => t.toUpperCase()));
const repeated = Array.from({length: 400000}, (_, i) => i % 2 ? 'REPEATED' : 'repeated');
for (let i = 0; i < 5; i++) uniqueTags(mixed.slice(0, 2000));
const times = [];
for (const input of [distinct, mixed, repeated]) {
  const start = performance.now();
  const output = uniqueTags(input);
  const elapsed = performance.now() - start;
  assert.ok(Array.isArray(output));
  assert.ok(elapsed < 900, `uniqueTags took ${elapsed.toFixed(1)} ms for ${input.length} tags; must stay well under a second`);
  times.push(elapsed);
}
console.log(times.reduce((sum, n) => sum + n, 0));
